llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Etodolac, a carboxylic acid with a fused-ring lipophilic core, has absolute oral bioavailability of 80% in humans, demonstrating that an ionizable carboxylic acid can achieve high F despite negative logD concerns.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "FK788, which contains the same carboxymethoxyaryl substructure as the query, was well absorbed with 55% oral bioavailability in healthy volunteers, directly supporting high F for the query's acid/ether motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Bevantolol, a high-transfer beta-blocker analogue, showed mean absolute bioavailability of 57% (range 26-98%) in healthy subjects, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "KNI-272, a high-transfer peptidomimetic, had absolute bioavailability of 36.40% when administered post-prandially, indicating that fed-state conditions do not reduce F below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A single pediatric record for KNI-272 reported 12% mean absolute bioavailability with a specific suspension vehicle, but this is an outlier relative to consistent adult fasting and post-prandial values above 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transferability analogues, including carboxylic-acid-containing etodolac (F≈80%) and FK788 (F=55%), and beta-blockers/peptidomimetics with F 30-57%, support F ≥ 20%. The only low value is a pediatric formulation outlier, and fed-state KNI-272 data also show F > 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule; extrapolation relies on analogues with high assay-transfer scores but not identical chemotypes.",
    "Fed-state effect for the query is inferred mainly from KNI-272 post-prandial data; other analogues were not explicitly tested under fed conditions.",
    "The absorption mechanism (active transport vs passive permeability) for the ionized carboxylic acid is not experimentally established."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

